+  });
+
+  it('should select and focus the target tab on ArrowRight in automatic mode', async () => {
+    const el = await fixture(html`
+      <cds-tabs>
+        <cds-tab value="tab-1" target="p-1">First</cds-tab>
+        <cds-tab value="tab-2" target="p-2">Second</cds-tab>
